    #[test]
    fn pdf_glyph_to_unicode_is_retained_in_format_state() {
        let mut f = Fast::new();
        init(&mut f);
        f.run(r"\pdfglyphtounicode{f_f}{0066 0066}\pdfglyphtounicode{A}{0041}");
        assert_eq!(
            f.glyph_to_unicode().get("f_f").map(|value| value.as_str()),
            Some("00660066")
        );
        assert_eq!(
            f.glyph_to_unicode().get("A").map(|value| value.as_str()),
            Some("0041")
        );

        let restored = Fast::undump(&f.dump().expect("dump")).expect("restore");
        assert_eq!(
            restored
                .glyph_to_unicode()
                .get("f_f")
                .map(|value| value.as_str()),
            Some("00660066")
        );
    }

    #[test]
    fn random_stream_continues_identically_after_snapshot_restore() {
        let mut original = Fast::new();
        init(&mut original);
        original.run(r"\pdfsetrandomseed 42 \number\pdfuniformdeviate 1000000,");
        let prefix_bytes = original.out_string().len();
        let mut restored = Fast::undump(&original.dump().expect("dump")).expect("restore");
        let suffix = r"\number\pdfuniformdeviate 1000000,\number\pdfnormaldeviate";
        original.run(suffix);
        restored.run(suffix);
        assert_eq!(
            restored.out_string(),
            &original.out_string()[prefix_bytes..]
        );
    }

    #[test]
    fn job_name_dependency_is_recorded_only_when_tex_reads_it() {
        let mut engine = Fast::new();
        init(&mut engine);
        engine.set_job_name("paper");
        engine.run(r"\relax");
        assert!(!engine.job_name_was_read());
        engine.run(r"\jobname");
        assert!(engine.job_name_was_read());
        let restored = Fast::undump(&engine.dump().expect("dump")).expect("restore");
        assert!(!restored.job_name_was_read());
    }

    #[test]
    fn format_restore_disables_per_run_token_diagnostics() {
        let mut f = Fast::new();
        init(&mut f);
        // These fields are intentionally skipped by serde. Their derived
        // defaults are zero, however, and a zero token window means "trace
        // every token from step zero" unless undump restores the off sentinel.
        f.dbg_tok_win = (12, 34);
        f.dbg_us_depth = 7;

        let restored = Fast::undump(&f.dump().expect("dump")).expect("restore");
        assert_eq!(restored.dbg_tok_win, (u64::MAX, 0));
        assert_eq!(restored.dbg_us_depth, -1);
    }

    #[test]
    fn native_text_uses_host_shaping_and_restores_preamble_selectors() {
        let mut f = Fast::new();
        init(&mut f);
        f.run(r"\aitexfont{Preferred Serif}\aitexlanguage{ar}");
        let mut restored = Fast::undump(&f.dump().expect("dump")).expect("restore");
        restored.typesetting = true;

        let requests = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let seen = std::rc::Rc::clone(&requests);
        restored.set_native_text_shaper(alloc::boxed::Box::new(move |request| {
            seen.borrow_mut().push(request.clone());
            Ok(Vec::new())
        }));
        restored.run("\\aitextext{السَّلَامُ} नमस्ते\\par");

        let requests = requests.borrow();
        assert_eq!(requests.len(), 2);
        assert_eq!(requests[0].text, "السَّلَامُ");
        assert_eq!(requests[1].text, "नमस्ते");
        assert!(
            requests
                .iter()
                .all(|request| request.family.as_deref() == Some("Preferred Serif"))
        );
        assert!(
            requests
                .iter()
                .all(|request| request.language.as_deref() == Some("ar"))
        );
    }

    #[test]
    fn native_utf8_input_does_not_feed_decoded_latin1_through_inputenc_bytes() {
        let mut f = Fast::new();
        init(&mut f);
        for code in 0x80..=0xff {
            f.catcodes.set(
                char::from_u32(code).expect("Latin-1 scalar"),
                CatCode::Active,
            );
        }
        f.enable_native_utf8_input();
        assert_eq!(f.catcodes.get('\u{a0}'), CatCode::Other);
        assert_eq!(f.catcodes.get('é'), CatCode::Letter);
        assert_eq!(f.catcodes.get('\u{ad}'), CatCode::Other);
    }

