    #[test]
    fn native_font_features_and_direction_follow_tex_group_scope() {
        let mut f = Fast::new();
        init(&mut f);
        f.typesetting = true;
        f.set_native_text_defaults(
            Some(alloc::string::String::from("Junicode")),
            Some(alloc::string::String::from("en")),
            Some(alloc::string::String::from("+liga")),
            Some(alloc::string::String::from("wght=450")),
            Some(alloc::string::String::from("ltr")),
            true,
        );
        let requests = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let seen = std::rc::Rc::clone(&requests);
        f.set_native_text_shaper(alloc::boxed::Box::new(move |request| {
            seen.borrow_mut().push(request.clone());
            Ok(Vec::new())
        }));
        f.run(
            "base{\\aitexfont{Amiri}\\aitexlanguage{ar}\\aitexfeatures{-liga}\\aitexvariations{}\\aitexdirection{rtl}inside}after\\par",
        );

        let requests = requests.borrow();
        assert_eq!(
            requests
                .iter()
                .map(|request| request.text.as_str())
                .collect::<Vec<_>>(),
            ["base", "inside", "after"]
        );
        assert_eq!(requests[1].family.as_deref(), Some("Amiri"));
        assert_eq!(requests[1].language.as_deref(), Some("ar"));
        assert_eq!(requests[1].features.as_deref(), Some("-liga"));
        assert_eq!(requests[1].variations, None);
        assert_eq!(requests[1].direction.as_deref(), Some("rtl"));
        assert_eq!(requests[2].family.as_deref(), Some("Junicode"));
        assert_eq!(requests[2].features.as_deref(), Some("+liga"));
        assert_eq!(requests[2].variations.as_deref(), Some("wght=450"));
        assert_eq!(requests[2].direction.as_deref(), Some("ltr"));
    }

