    /// listofitems does not merely ask whether e-TeX's version identifier is
    /// defined: it compares `\meaning` with `\string` to prove that it is the
    /// primitive. A chardef-like integer has the right value but fails that
    /// identity check and makes an otherwise ordinary LaTeX job abort.
    #[test]
    fn etex_version_is_an_internal_integer_primitive() {
        assert_eq!(
            run_str(
                &[
                    INITEX_BRACES,
                    r"\edef\a{\meaning\eTeXversion}\edef\b{\string\eTeXversion}",
                    r"\ifx\a\b T\else F\fi,\the\eTeXversion,\the\eTeXminorversion",
                ]
                .concat()
            ),
            "T,2,6"
        );
    }

    #[test]
    fn pdftex_banner_is_expandable_and_matches_the_advertised_version() {
        assert_eq!(
            run_str(&[INITEX_BRACES, r"\edef\banner{\pdftexbanner}", r"\banner",].concat()),
            "This is aiTeX, compatible with pdfTeX 3.141592653-2.6-1.40.25"
        );
    }

    /// e-TeX §3.7 exposes the two non-width components of a glue specification
    /// both as dimensions and as their order numbers (normal=0, fil=1,
    /// fill=2, filll=3). These spellings are used through expl3 aliases by
    /// xfrac and derivative.
    #[test]
    fn etex_glue_component_queries_scan_a_glue_spec() {
        assert_eq!(
            run_str(
                &[
                    INITEX_BRACES,
                    r"\the\gluestretch 1pt plus 2fil minus 3fill;",
                    r"\the\glueshrink 1pt plus 2fil minus 3fill;",
                    r"\the\gluestretchorder 1pt plus 2fil minus 3fill;",
                    r"\the\glueshrinkorder 1pt plus 2fil minus 3fill",
                ]
                .concat()
            ),
            "2.0pt;3.0pt;1;2"
        );
    }

    /// `\gluestretch` and `\glueshrink` are internal dimensions when they
    /// occur in a dimension scanner. In particular they take no trailing unit;
    /// Bigfoot uses this exact pair of comparisons to select its output path.
    #[test]
    fn etex_glue_components_are_dimensions_in_ifdim() {
        assert_eq!(
            run_str(
                &[
                    INITEX_BRACES,
                    r"\skip0=-10pt plus 2pt minus 3pt",
                    r"\ifdim\skip0>-\gluestretch\skip0 T\else F\fi;",
                    r"\ifdim\skip0<\glueshrink\skip0 T\else F\fi",
                ]
                .concat()
            ),
            "F;T"
        );
    }

