    #[test]
    fn pdf_forms_share_object_numbers_and_take_ownership_of_the_box() {
        let mut f = Fast::new();
        init(&mut f);
        f.typesetting = true;
        f.run(
            &[
                INITEX_BRACES,
                r"\pdfobj reserveobjnum\setbox7=\hbox{}\wd7=3pt\pdfxform7",
                r"\pdfobj{/Kind/Test}",
            ]
            .concat(),
        );
        let last_obj = f.interner.borrow_mut().intern("pdflastobj");
        let last_xform = f.interner.borrow_mut().intern("pdflastxform");
        assert_eq!(f.named_of_sym(last_obj), 3);
        assert_eq!(f.named_of_sym(last_xform), 2);
        assert!(!f.ts.boxes.contains_key(&7));
        assert_eq!(f.pdf_forms.get(&2), Some(&[3 * 65_536, 0, 0]));
    }

    #[test]
    fn pdf_forms_are_transported_only_for_final_pdf_output() {
        fn transported(final_pdf: bool) -> (usize, usize) {
            let mut f = Fast::new();
            init(&mut f);
            f.typesetting = true;
            f.force_dvi_output_mode(final_pdf);
            f.run(
                &[
                    INITEX_BRACES,
                    r"\setbox0=\hbox to3pt{}",
                    r"\pdfxform resources{/ProcSet[/PDF]}0",
                    r"\pdfrefxform\pdflastxform",
                ]
                .concat(),
            );
            let boxes =
                f.ts.vlist
                    .iter()
                    .filter(|node| matches!(node, crate::node::Node::Box(_)))
                    .count();
            let whatsits =
                f.ts.vlist
                    .iter()
                    .filter_map(|node| match node {
                        crate::node::Node::Box(boxed) => Some(
                            boxed
                                .list
                                .iter()
                                .filter(|inner| matches!(inner, crate::node::Node::Whatsit(_)))
                                .count(),
                        ),
                        _ => None,
                    })
                    .sum();
            (boxes, whatsits)
        }

        assert_eq!(transported(false), (0, 0));
        assert_eq!(transported(true), (2, 4));
    }

