    #[test]
    fn pdf_color_stack_scanners_allocate_and_consume_actions() {
        use alloc::rc::Rc;
        use core::cell::RefCell;

        let pages = Rc::new(RefCell::new(Vec::new()));
        let captured = Rc::clone(&pages);
        let mut f = Fast::new();
        init(&mut f);
        f.typesetting = true;
        f.set_page_sink(alloc::boxed::Box::new(move |page, _, _| {
            captured.borrow_mut().push(page.clone());
        }));
        f.run(
            &[
                INITEX_BRACES,
                r"\chardef\a=\pdfcolorstackinit direct {0 g}\relax",
                r"\xdef\b{\pdfcolorstackinit page direct {/TRP1 gs}}",
                r"[\the\a,\b]",
                r"\setbox0=\hbox{A",
                r"\pdfcolorstack\a push {1 0 0 rg}",
                r"\pdfcolorstack\a current\relax",
                r"\pdfcolorstack\a set {0 1 0 rg}",
                r"\pdfcolorstack\a pop\relax",
                r"\pdfcolorstack\b push {/TRP.5 gs}",
                r"\pdfcolorstack\b pop\relax B}",
                r"\shipout\box0",
            ]
            .concat(),
        );
        assert_eq!(f.out_string(), "[1,2]AB");
        let mut specials = alloc::vec::Vec::new();
        fn collect(node: &crate::node::Node, out: &mut alloc::vec::Vec<alloc::string::String>) {
            match node {
                crate::node::Node::Whatsit(text) => out.push(text.clone()),
                crate::node::Node::Box(inner) => {
                    for node in &inner.list {
                        collect(node, out);
                    }
                }
                _ => {}
            }
        }
        for page in pages.borrow().iter() {
            for node in &page.list {
                collect(node, &mut specials);
            }
        }
        assert!(
            specials
                .iter()
                .any(|special| special == "aitex:pdfcolorstackinit 2 /TRP1 gs"),
            "{specials:?}"
        );
    }

