    #[test]
    fn etex_penalty_arrays_assign_query_repeat_and_restore() {
        assert_eq!(
            run_str(
                &[
                    INITEX_BRACES,
                    r"\clubpenalties=2 100 200 ",
                    r"[\the\clubpenalties0,\the\clubpenalties1,\the\clubpenalties3]",
                    r"{\clubpenalties 1 9 [\the\clubpenalties1]}",
                    r"[\the\clubpenalties1]",
                ]
                .concat()
            ),
            "[2,100,200][9][100]"
        );
    }

    /// §325's `back_input` discards an exhausted u-template before it puts the
    /// token back; only a v-template is retained. The distinction matters to
    /// expl3's alignment-safe lookahead, which deliberately backs up the final
    /// token of a u-template before changing `align_state` by one.
    #[test]
    fn back_input_pops_an_exhausted_u_template() {
        let mut f = Fast::new();
        f.align_mode.push((
            (crate::fastset::Mode::Vertical, false),
            (crate::fastset::Mode::Vertical, true),
            f.ts.open.len(),
        ));
        let t = Token::Char('x', CatCode::Other);
        f.push_u_template(&[t]);
        assert_eq!(f.get_next(), Some(t));
        assert_eq!(f.align_state, 1_000_000);

        f.back(t);
        assert_eq!(f.align_state, 0);
        assert!(!f.cur.utmpl, "the spent u-template must have been popped");
        assert_eq!(f.get_next(), Some(t));
    }

    #[test]
    fn def_and_expand() {
        // \def\a{XY}\def\b#1{[#1]}\a\b{Z} -> XY[Z]
        let mut f = Fast::new();
        init(&mut f);
        f.run("\\def\\a{XY}\\def\\b#1{[#1]}\\a\\b{Z}");
        assert_eq!(f.out_string(), "XY[Z]");
    }

    /// `tex.web` §277: a group saves an entry the first time it assigns it and
    /// not again — so a group that redefines one control sequence a thousand
    /// times leaves one save entry, not a thousand, and the 998 intermediate
    /// bodies are garbage the moment they are overwritten. What the group
    /// restores is the value from *before* it, which is what this checks.
    #[test]
    fn a_group_saves_a_control_sequence_once() {
        let mut f = Fast::new();
        init(&mut f);
        f.run(r"\def\a{o}{\def\a{1}\def\a{2}\def\a{3}[\a]}[\a]");
        assert_eq!(f.out_string(), "[3][o]");
        assert!(
            f.save_stack.is_empty(),
            "the group closed; nothing should still be saved"
        );
    }

    /// §283: a `\global` assignment inside a group *destroys* the saved value
    /// rather than restoring it, and drops the entry to `level_one` — so a later
    /// local assignment in the same group must save again, and the group end
    /// must land on the global value, not the one from before the group.
    #[test]
    fn a_global_assignment_survives_the_group_that_made_it() {
        let mut f = Fast::new();
        init(&mut f);
        f.run(r"\def\a{o}{\def\a{in}\global\def\a{g}[\a]}[\a]");
        assert_eq!(f.out_string(), "[g][g]");
        let mut f = Fast::new();
        init(&mut f);
        f.run(r"\def\a{o}{\global\def\a{g}\def\a{loc}[\a]}[\a]");
        assert_eq!(f.out_string(), "[loc][g]");
    }

    /// The arena is append-only, so overwritten bodies pile up in it; the
    /// collector drops what no meaning names. Nothing observable may change.
    #[test]
    fn compaction_keeps_only_what_is_reachable() {
        let mut f = Fast::new();
        init(&mut f);
        // Enough redefinition to leave far more garbage than live body.
        let mut src = alloc::string::String::from(r"\def\keep{KEPT}");
        for i in 0..500 {
            let _ = core::fmt::Write::write_fmt(
                &mut src,
                format_args!("\\def\\churn{{body number {i} with several tokens in it}}"),
            );
        }
        f.run(&src);
        let before = f.arena.len();
        f.compact_arena();
        assert!(
            f.arena.len() * 4 < before,
            "compaction should drop most of {before} words, kept {}",
            f.arena.len()
        );
        f.run(r"[\keep][\churn]");
        assert_eq!(
            f.out_string(),
            "[KEPT][body number 499 with several tokens in it]"
        );
    }

    /// `\meaning` prints the prefixes a macro was defined with, and expl3 and
    /// LaTeX both read meanings back as strings. Every string here was taken from
    /// `pdftex -ini -etex`, including the placement of the single space: it belongs
    /// to the *last* prefix, so `\protected\long macro:` has none in the middle.
    #[test]
    fn meaning_prints_long_and_protected() {
        let mut f = Fast::new();
        init(&mut f);
        f.run(concat!(
            r"\long\def\la#1{x}",
            r"\def\pn#1{y}",
            r"\protected\def\po#1{p}",
            r"\long\protected\def\lp#1{z}",
            r"\let\cop\la",
            r"[\meaning\la][\meaning\pn][\meaning\po][\meaning\lp]",
            r"[\meaning\cop][\meaning\long][\meaning\outer]",
        ));
        assert_eq!(
            f.out_string(),
            concat!(
                r"[\long macro:#1->x][macro:#1->y][\protected macro:#1->p]",
                r"[\protected\long macro:#1->z][\long macro:#1->x][\long][\outer]",
            )
        );
    }

    /// `tex.web` §470 selects `new_string` while constructing the expandable
    /// result of `\meaning`. Unlike a terminal/log diagnostic, that internal
    /// string retains eight-bit macro-body characters verbatim. url.sty relies
    /// on this to verbatimise UTF-8 byte sequences.
    #[test]
    fn meaning_expansion_keeps_eight_bit_macro_body_characters_raw() {
        assert_eq!(
            run_str(r#"\catcode94=7 \catcode"EF=12 \def\a{^^ef}\meaning\a"#),
            "macro:->\u{ef}"
        );

        let mut f = Fast::new();
        init(&mut f);
        f.run(r#"\catcode94=7 \catcode"EF=12 \def\a{^^ef}\show\a"#);
        assert!(
            f.messages.iter().any(|line| line.contains("^^ef")),
            "displayed meanings must remain terminal-safe: {:?}",
            f.messages
        );
    }

    /// `\long`-ness is part of a definition, so a group must restore it along
    /// with the meaning — the flag lives in its own table and was, at first,
    /// left behind by `unsave`.
    #[test]
    fn long_is_restored_at_group_end() {
        let mut f = Fast::new();
        init(&mut f);
        f.run(r"\def\a{o}{\long\def\a{i}[\meaning\a]}[\meaning\a]");
        assert_eq!(f.out_string(), r"[\long macro:->i][macro:->o]");
    }

    /// `tex.web` §241: the host supplies the clock, and nothing else may.
    #[test]
    fn clock_parameters_come_from_the_host() {
        let mut f = Fast::new();
        init(&mut f);
        f.run(r"[\the\time|\the\day|\the\month|\the\year]");
        assert_eq!(f.out_string(), "[0|0|0|0]");
        let mut f = Fast::new();
        init(&mut f);
        f.set_clock(9 * 60 + 41, 4, 8, 2026);
        f.run(r"[\the\time|\the\day|\the\month|\the\year]");
        assert_eq!(f.out_string(), "[581|4|8|2026]");
    }

