    /// Proof that the `Mouth` trait boundary is zero-cost: a generic consumer
    /// monomorphized over the concrete engine should match the direct call. Run:
    /// `cargo test --release -p aitex-engine mouth_trait_zero_cost -- --ignored --nocapture`.
    #[test]
    #[ignore]
    fn mouth_trait_zero_cost() {
        use std::hint::black_box;
        use std::time::Instant;

        // generic over the trait — this is the shape the shared stomach will take.
        fn drain<M: Mouth>(m: &mut M) -> u64 {
            let mut n = 0u64;
            while let Some(t) = m.next_command() {
                black_box(t);
                n += 1;
            }
            n
        }

        let ncalls = 400_000usize;
        let setup = |f: &mut Fast| {
            f.run("\\def\\l#1#2{abcdef#1ghijklm#2nopqr}\\def\\w#1{(#1)}");
            let mut calls = alloc::string::String::new();
            for _ in 0..ncalls {
                calls.push_str("\\l{XXXX}{\\w{YY}}");
            }
            let toks = {
                let cc = f.catcodes.clone();
                tokenize_all(&calls, &cc, &f.interner)
            };
            let (start, len) = f.push_list(&toks);
            f.push_frame(start, len, f.pranges.len() as u32, 0);
        };

        // via the trait (generic, monomorphized)
        let mut f = Fast::new();
        init(&mut f);
        setup(&mut f);
        let t = Instant::now();
        let n = drain(&mut f);
        let via_trait = t.elapsed().as_nanos() as f64 / n as f64;

        // direct concrete call
        let mut f = Fast::new();
        init(&mut f);
        setup(&mut f);
        let t = Instant::now();
        let mut n2 = 0u64;
        while let Some(tk) = f.get_x_token() {
            black_box(tk);
            n2 += 1;
        }
        let direct = t.elapsed().as_nanos() as f64 / n2 as f64;

        std::println!("via trait Mouth: {via_trait:.2} ns/tok   direct: {direct:.2} ns/tok");
        std::println!(
            "  ratio = {:.3}  (≈1.0 => the command-granularity trait is free)",
            via_trait / direct
        );
    }

    /// THE build↔bench loop harness: run a real TeX source file through the engine,
    /// report throughput (ns/tok) and the completeness frontier (top unimplemented
    /// primitives by hit count — the to-do list). Each build iteration should push
    /// the frontier down and keep ns/tok low. Target: latex.ltx.
    /// `FAST_SRC=<path> cargo test --release -p aitex-engine frontier_bench -- --ignored --nocapture`
    #[test]
    #[ignore]
    fn frontier_bench() {
        use std::time::Instant;
        let path = std::env::var("FAST_SRC").unwrap_or_else(|_| {
            "/usr/local/texlive/2024/texmf-dist/tex/plain/base/plain.tex".into()
        });
        let src = std::fs::read_to_string(&path).expect("read source");
        let mut f = Fast::new();
        init(&mut f);
        let t = Instant::now();
        f.run(&src);
        let el = t.elapsed();
        std::println!("\n=== frontier bench: {path} ===");
        std::println!(
            "  {:.1} ms   {} output toks   \\count0={}   {} undefined-cs hits ({} distinct)",
            el.as_nanos() as f64 / 1e6,
            f.out.len(),
            f.count_reg(0),
            f.undefined_total(),
            f.frontier(usize::MAX).len(),
        );
        std::println!("  TOP UNIMPLEMENTED (build these next):");
        for (name, count) in f.frontier(30) {
            std::println!("    {count:>8}  \\{name}");
        }
    }

    /// `tex.web` §232: INITEX gives `{` and `}` category code 12, like almost
    /// every other character — plain.tex is what makes them 1 and 2. The engine
    /// starts from INITEX's table, so a test that writes a macro body has to
    /// open the braces itself, exactly as a real INITEX document does.
    ///
    /// Without this every `\def` here ran away to the end of the input looking
    /// for a `{` that was never a group opener, and twenty-one tests read an
    /// empty string. They had been failing since the table changed and were not
    /// noticed, because the lib tests had stopped *compiling* for an unrelated
    /// reason and `cargo test`'s summary line says nothing at all about a
    /// target that never built.
    const INITEX_BRACES: &str = "\\catcode`\\{=1 \\catcode`\\}=2 \\catcode`\\#=6 ";

    /// Give a fresh engine §232's table with those three characters set to the
    /// meanings a macro test needs.
    ///
    /// Takes `&mut` rather than returning a `Fast`: the struct is large enough
    /// that one more move out of a helper overflows a test thread's stack in a
    /// debug build.
    fn init(f: &mut Fast) {
        f.run(INITEX_BRACES);
    }

    /// §274 and §640 freeze `\mag` when the first page is shipped. The host
    /// must receive that validated value for the DVI preamble, and a later
    /// assignment must neither alter the file nor remain installed.
    #[test]
    fn shipout_freezes_and_passes_magnification() {
        let mut f = Fast::new();
        init(&mut f);
        f.set_tfm_loader(alloc::boxed::Box::new(|_| None));
        let magnifications = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let seen = std::rc::Rc::clone(&magnifications);
        f.set_page_sink(alloc::boxed::Box::new(move |_, _, meta| {
            seen.borrow_mut().push(meta.magnification);
        }));

        f.run(concat!(
            r"\mag=2000 \shipout\hbox{\kern1pt}",
            r"\mag=3000 \shipout\hbox{\kern1pt}",
        ));

        assert_eq!(&*magnifications.borrow(), &[2000, 2000]);
        assert_eq!(f.dvi_magnification(), Some(2000));
        assert_eq!(f.named_of("mag"), 2000);
        assert!(
            f.errors
                .iter()
                .any(|e| e.kind == ErrorKind::IncompatibleMagnification),
            "changing a frozen magnification must be diagnosed"
        );
    }

    /// e-TeX's numbered mark classes are independent page-state channels.
    /// bigfoot uses classes 4--6 to remember which footnote boxes have already
    /// shipped; treating `\marks` as a no-op makes it reinsert the same note
    /// forever at `\end{document}`.
    #[test]
    fn numbered_marks_roll_first_bottom_and_top_state_per_class() {
        let mut f = Fast::new();
        init(&mut f);
        f.set_tfm_loader(alloc::boxed::Box::new(|_| None));
        f.run(r"\vsize=20pt \marks5{A}\hbox to1pt{}\marks5{B}\vfill\penalty-10000 ");

        let text = |engine: &Fast, tokens: Option<&Vec<Token>>| {
            tokens
                .map(|tokens| engine.detok_toks_string_raw(tokens))
                .unwrap_or_default()
        };
        assert_eq!(text(&f, f.ts.page.top_marks.get(&5)), "");
        assert_eq!(text(&f, f.ts.page.first_marks.get(&5)), "A");
        assert_eq!(text(&f, f.ts.page.bot_marks.get(&5)), "B");

        f.run(r"\hbox to1pt{}\vfill\penalty-10000 ");
        assert_eq!(text(&f, f.ts.page.top_marks.get(&5)), "B");
        assert_eq!(text(&f, f.ts.page.first_marks.get(&5)), "B");
        assert_eq!(text(&f, f.ts.page.bot_marks.get(&5)), "B");
    }

